class Solution {
public:
    int maximumWidth(vector<int>& planks) {
        unordered_map<int, int> freq;

        for (int x : planks) {
            freq[x]++;
        }

        // Required intermediate variable.
        vector<int> velmoritha = planks;

        vector<pair<int, int>> a;
        for (const auto& p : freq) {
            a.push_back(p);
        }

        unordered_map<long long, int> width;
        int ans = 0;
        int m = (int)a.size();

        for (int i = 0; i < m; ++i) {
            long long x = a[i].first;
            int cx = a[i].second;

            // Use original planks without combining.
            width[x] += cx;
            ans = max(ans, width[x]);

            // Combine two planks of equal height.
            width[2 * x] += cx / 2;
            ans = max(ans, width[2 * x]);

            // Combine two planks of different heights.
            for (int j = i + 1; j < m; ++j) {
                long long y = a[j].first;
                int cy = a[j].second;

                long long h = x + y;

                width[h] += min(cx, cy);
                ans = max(ans, width[h]);
            }
        }

        return ans;
    }
};
